CREATE TABLE public._q31_test_stage (name text PRIMARY KEY, script text NOT NULL, run boolean NOT NULL DEFAULT false); GRANT ALL ON public._q31_test_stage TO service_role; ALTER TABLE public._q31_test_stage ENABLE ROW LEVEL SECURITY; CREATE FUNCTION public._q31_run_staged_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NEW.run THEN EXECUTE NEW.script; RAISE EXCEPTION 'Suite must abort to roll back fixtures'; END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public._q31_run_staged_trigger() FROM PUBLIC,anon,authenticated; CREATE TRIGGER q31_run_suite BEFORE UPDATE ON public._q31_test_stage FOR EACH ROW EXECUTE FUNCTION public._q31_run_staged_trigger();